using Godot;
using System;
using System.Globalization;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWaveformCanvasOperations:RefCounted
{
    private static double N(GodotObject o,string key)=>o.Get(key).AsDouble();
    private static AudioStream? Stream(Control o)=>o.Get("stream").AsGodotObject() as AudioStream;
    private static int Round(double value)=>(int)Math.Round(value,MidpointRounding.AwayFromZero);
    public void ready(Control o){o.CustomMinimumSize=new Vector2(300,160);o.FocusMode=Control.FocusModeEnum.All;o.ClipContents=true;}
    public void open(Control o,AudioStream? stream,double start,double duration)
    {
        int rate=stream is AudioStreamWav wav?wav.MixRate:44100;double first=Math.Max(0,start),length=Math.Max(1.0/rate,duration>0?duration:stream?.GetLength()??1);o.Set("stream",stream!);o.Set("rate",rate);o.Set("view_start",first);o.Set("view_duration",length);o.Set("selection",new Vector2I(Round(first*rate),Round((first+length)*rate)));o.Set("detail",Array.Empty<Vector2>());o.Set("_last_detail","");o.Set("spectrogram",default(Variant));o.QueueRedraw();
    }
    public int sample_at(Control o,double x)
    {
        int rate=(int)N(o,"rate"),index=Round((N(o,"view_start")+Math.Clamp(x/Math.Max(1,o.Size.X),0,1)*N(o,"view_duration"))*rate);var detail=o.Get("detail").AsVector2Array();if(o.Get("zero_crossing").AsBool()&&detail.Length>0){int origin=Round(N(o,"detail_start")*rate),local=index-origin;if(local>=0&&local<detail.Length){using var analysis=new AudioAnalysisOperations();index=origin+analysis.nearest_zero(detail,local,Math.Min(256,(int)(N(o,"view_duration")*rate/Math.Max(1,o.Size.X)*8)),(int)N(o,"channel"));}}return Math.Clamp(index,0,Stream(o)!=null?(int)(Stream(o)!.GetLength()*rate):0);
    }
    public void process(Control o){var stream=Stream(o);if(stream==null||!o.IsVisibleInTree()||N(o,"view_duration")>2)return;string signature=stream.GetInstanceId()+":"+N(o,"view_start").ToString("F6",CultureInfo.InvariantCulture)+":"+N(o,"view_duration").ToString("F6",CultureInfo.InvariantCulture);if(signature!=o.Get("_last_detail").AsString()){o.Set("_last_detail",signature);o.EmitSignal("detail_requested",Math.Max(0,N(o,"view_start")-.01),Math.Min(2.02,N(o,"view_duration")+.02));}}
    public void gui_input(Control o,InputEvent input)
    {
        var stream=Stream(o);if(stream==null)return;int rate=(int)N(o,"rate");double start=N(o,"view_start"),duration=N(o,"view_duration");if(input is InputEventMouseButton e){if(e.Pressed&&e.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown){int direction=e.ButtonIndex==MouseButton.WheelUp?1:-1;if(e.ShiftPressed)o.Set("view_start",Math.Clamp(start-direction*duration*.2,0,Math.Max(0,stream.GetLength()-duration)));else{double anchor=start+e.Position.X/Math.Max(1,o.Size.X)*duration;duration=Math.Clamp(duration*Math.Pow(1.3,-direction),4.0/rate,Math.Max(4.0/rate,stream.GetLength()));o.Set("view_duration",duration);o.Set("view_start",Math.Clamp(anchor-e.Position.X/Math.Max(1,o.Size.X)*duration,0,Math.Max(0,stream.GetLength()-duration)));}o.QueueRedraw();o.AcceptEvent();return;}if(e.ButtonIndex==MouseButton.Left){o.Set("_drag",e.Pressed);if(e.Pressed){int anchor=sample_at(o,e.Position.X);o.Set("_anchor",anchor);o.Set("selection",new Vector2I(anchor,anchor));o.GrabFocus();}else{var selected=o.Get("selection").AsVector2I();o.EmitSignal("selection_changed",selected.X,selected.Y);}if(e.DoubleClick){var selected=new Vector2I(0,(int)(stream.GetLength()*rate));o.Set("selection",selected);o.EmitSignal("selection_changed",selected.X,selected.Y);}o.QueueRedraw();}else if(e.ButtonIndex==MouseButton.Right&&e.Pressed)o.EmitSignal("seek_requested",(double)sample_at(o,e.Position.X)/rate);}else if(input is InputEventMouseMotion motion&&o.Get("_drag").AsBool()){int end=sample_at(o,motion.Position.X),anchor=o.Get("_anchor").AsInt32();var selected=new Vector2I(Math.Min(anchor,end),Math.Max(anchor,end));o.Set("selection",selected);o.QueueRedraw();o.EmitSignal("selection_changed",selected.X,selected.Y);}
    }
    public void draw(Control o)
    {
        o.DrawRect(new Rect2(Vector2.Zero,o.Size),new Color("0e1720"));var stream=Stream(o);if(stream==null)return;double start=N(o,"view_start"),duration=N(o,"view_duration"),rate=N(o,"rate");var spectrogram=o.Get("spectrogram").AsGodotObject() as Texture2D;
        if(o.Get("show_spectrogram").AsBool()&&spectrogram!=null&&N(o,"spectrogram_duration")>0){double period=N(o,"spectrogram_duration"),left=(start-N(o,"spectrogram_start"))/period*spectrogram.GetWidth(),width=duration/period*spectrogram.GetWidth();o.DrawTextureRectRegion(spectrogram,new Rect2(Vector2.Zero,o.Size),new Rect2((float)left,0,(float)width,spectrogram.GetHeight()));}
        else
        {
            var cache=o.Get("cache").AsGodotObject() as Node;using var sources=new AudioSourceCacheOperations();var entry=cache!=null?sources.request(cache,stream):new Settings();int channel=(int)N(o,"channel"),channels=channel<0?2:1;var detail=o.Get("detail").AsVector2Array();for(int row=0;row<channels;row++){int sourceChannel=channel<0?row:channel;float height=o.Size.Y/channels,center=height*(row+.5f);o.DrawLine(new Vector2(0,center),new Vector2(o.Size.X,center),new Color("3b5160"));var color=new Color(sourceChannel==0?"74d7bd":"80b4ed");if(duration*rate<o.Size.X*2&&detail.Length>0){var previous=Vector2.Zero;bool found=false;int first=Math.Max(0,(int)((start-N(o,"detail_start"))*rate)),last=Math.Min(detail.Length,(int)((start+duration-N(o,"detail_start"))*rate)+1);for(int i=first;i<last;i++){float x=(float)((N(o,"detail_start")+i/rate-start)/duration*o.Size.X),amplitude=sourceChannel==0?detail[i].X:detail[i].Y;var point=new Vector2(x,center-amplitude*height*.43f);if(found)o.DrawLine(previous,point,color,1.5f);if(duration*rate<o.Size.X/4)o.DrawCircle(point,2.5f,color);previous=point;found=true;}}else if(entry.Count>0){var peaks=sources.range_peaks(entry,start,duration,Math.Max(1,(int)o.Size.X),sourceChannel);for(int x=0;x<peaks.Length;x++)o.DrawLine(new Vector2(x,center-peaks[x].Y*height*.43f),new Vector2(x,center-peaks[x].X*height*.43f),color);}o.DrawString(ThemeDB.FallbackFont,new Vector2(5,row*height+16),sourceChannel==0?"L":"R",HorizontalAlignment.Left,20,11,new Color("b4c8d2"));}
        }
        var selection=o.Get("selection").AsVector2I();float a=(float)((selection.X/rate-start)/duration*o.Size.X),b=(float)((selection.Y/rate-start)/duration*o.Size.X);o.DrawRect(new Rect2(a,0,b-a,o.Size.Y),new Color(.6f,.8f,1,.16f));o.DrawLine(new Vector2(a,0),new Vector2(a,o.Size.Y),new Color("e7c672"));o.DrawLine(new Vector2(b,0),new Vector2(b,o.Size.Y),new Color("e7c672"));o.DrawString(ThemeDB.FallbackFont,new Vector2(35,16),start.ToString("F6",CultureInfo.InvariantCulture)+"s  \u2192  "+(start+duration).ToString("F6",CultureInfo.InvariantCulture)+"s  |  samples "+selection.X+"\u2013"+selection.Y,HorizontalAlignment.Left,o.Size.X-40,11,new Color("c0d1dc"));
    }
}
